-- GATE PACK 0266 audit_sequence (POST-APPLY read-back). Read-only catalog SELECT, no writes, no table data. Generated by gate-packs/mkpacks.py; do not edit by hand.
select c.relname as obj, r.role, coalesce(concat_ws(',', case when has_sequence_privilege(r.role, c.oid, 'USAGE') then 'usage' end, case when has_sequence_privilege(r.role, c.oid, 'SELECT') then 'select' end, case when has_sequence_privilege(r.role, c.oid, 'UPDATE') then 'update' end), '') as privs
from pg_catalog.pg_class c
cross join (values ('anon'), ('authenticated'), ('service_role')) as r(role)
where c.oid in (pg_catalog.to_regclass('public.client_legal_name_access_audit_id_seq'))
order by 1, 2;
